import {matchPath} from '@docusaurus/router';
import {
  toVersionPathWithLeadingSlash,
  toVersionPathWithoutTrailingSlash,
  toVersionPathWithTrailingSlash,
  unwrapVersionPathError,
} from '../constants';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
  ActivePlugin,

display.text:
/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {matchPath} from '@docusaurus/router';
import {
  toVersionPathWithLeadingSlash,
  toVersionPathWithoutTrailingSlash,
  toVersionPathWithTrailingSlash,
  unwrapVersionPathError,
} from '../constants';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
  ActivePlugin,
  ActiveDocContext,
  DocVersionSuggestions,
} from '@docusaurus/plugin-content-docs/client';
import type {UseDataOptions} from '@docusaurus/types';

// This code is not part of the api surface, not in ./theme on purpose

// get the data of the plugin that is currently "active"
// ie the docs of that plugin are currently browsed
// it is useful to support multiple docs plugin instances
export function getActivePlugin(
  allPluginData: {[pluginId: string]: GlobalPluginData},
  pathname: string,
  options: UseDataOptions = {},
): ActivePlugin | undefined {
  const activeEntry = Object.entries(allPluginData)
    // Route sorting: '/android/foo' should match '/android' instead of '/'
    .sort((a, b) => b[1].path.localeCompare(a[1].path))
    .find(
      ([, pluginData]) =>
        !!matchPath(pathname, {
          path: pluginData.path,
          exact: false,
          strict: false,
        }),
    );

  const activePlugin: ActivePlugin | undefined = activeEntry
    ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
    : undefined;

  if (!activePlugin && options.failfast) {
    throw new Error(
      `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${Object.values(
        allPluginData,
      )
        .map((plugin) => plugin.path)
        .join(', ')}`,
    );
  }

  return activePlugin;
}

export const getLatestVersion = (data: GlobalPluginData): GlobalVersion =>
  data.versions.find((version) => version.isLast)!;

export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  try {
    const versions = data.versions;
    const pluginPath = data.path;
    const pathnameValue = pathname;
    let pathnameWithLeadingSlash = pathnameValue;
    if (!pathnameValue.startsWith('/')) {
      pathnameWithLeadingSlash = toVersionPathWithLeadingSlash(pathnameValue);
    }
    let pathnameWithTrailingSlash = pathnameValue;
    if (!pathnameValue.endsWith('/')) {
      pathnameWithTrailingSlash = toVersionPathWithTrailingSlash(pathnameValue);
    }
    let pathnameWithoutTrailingSlash = pathnameValue;
    if (pathnameValue !== '/' && pathnameValue.endsWith('/')) {
      pathnameWithoutTrailingSlash =
        toVersionPathWithoutTrailingSlash(pathnameValue);
    }

    const pathnameSegments: string[] = [];
    const rawPathnameSegments = pathnameValue.split('/');
    for (
      let segmentIndex = 0;
      segmentIndex < rawPathnameSegments.length;
      segmentIndex += 1
    ) {
      const rawSegment = rawPathnameSegments[segmentIndex]!;
      const normalizedSegment = rawSegment.trim();
      if (normalizedSegment.length > 0) {
        pathnameSegments.push(normalizedSegment);
      }
    }

    let pluginPathMatches = true;
    if (typeof pluginPath === 'string' && pluginPath.length > 0) {
      const pluginPathMatch = matchPath(pathname, {
        path: pluginPath,
        exact: false,
        strict: false,
      });
      pluginPathMatches = !!pluginPathMatch;
    }

    let lastVersion: GlobalVersion | undefined;
    for (
      let versionIndex = 0;
      versionIndex < versions.length;
      versionIndex += 1
    ) {
      const version = versions[versionIndex]!;
      if (version.isLast) {
        lastVersion = version;
        break;
      }
    }

    // Last version is a route like /docs/*,
    // we need to match it last or it would match /docs/version-1.0/* as well
    const versionsToMatch: Array<GlobalVersion | undefined> = [];
    for (
      let versionIndex = 0;
      versionIndex < versions.length;
      versionIndex += 1
    ) {
      const version = versions[versionIndex];
      if (version !== lastVersion) {
        versionsToMatch.push(version);
      }
    }
    versionsToMatch.push(lastVersion);

    for (
      let versionIndex = 0;
      versionIndex < versionsToMatch.length;
      versionIndex += 1
    ) {
      const version = versionsToMatch[versionIndex] as GlobalVersion;
      const versionPath = version.path;
      let versionPathWithLeadingSlash = versionPath;
      if (!versionPath.startsWith('/')) {
        versionPathWithLeadingSlash =
          toVersionPathWithLeadingSlash(versionPath);
      }
      let versionPathWithTrailingSlash = versionPath;
      if (!versionPath.endsWith('/')) {
        versionPathWithTrailingSlash =
          toVersionPathWithTrailingSlash(versionPath);
      }
      let versionPathWithoutTrailingSlash = versionPath;
      if (versionPath !== '/' && versionPath.endsWith('/')) {
        versionPathWithoutTrailingSlash =
          toVersionPathWithoutTrailingSlash(versionPath);
      }

      const versionSegments: string[] = [];
      const rawVersionSegments = versionPath.split('/');
      for (
        let segmentIndex = 0;
        segmentIndex < rawVersionSegments.length;
        segmentIndex += 1
      ) {
        const rawSegment = rawVersionSegments[segmentIndex]!;
        const normalizedSegment = rawSegment.trim();
        if (normalizedSegment.length > 0) {
          versionSegments.push(normalizedSegment);
        }
      }

      let matched = false;
      if (pathnameValue === versionPath) {
        matched = !!matchPath(pathname, {
          path: versionPath,
          exact: false,
          strict: false,
        });
      } else if (
        pathnameWithTrailingSlash === versionPathWithTrailingSlash ||
        pathnameWithoutTrailingSlash === versionPathWithoutTrailingSlash ||
        pathnameWithLeadingSlash === versionPathWithLeadingSlash
      ) {
        if (pathnameValue.endsWith('/')) {
          if (versionPath.endsWith('/') || versionPath === '/') {
            if (pluginPathMatches) {
              matched = !!matchPath(pathname, {
                path: versionPath,
                exact: false,
                strict: false,
              });
            } else {
              matched = !!matchPath(pathname, {
                path: versionPath,
                exact: false,
                strict: false,
              });
            }
          } else {
            matched = !!matchPath(pathname, {
              path: versionPath,
              exact: false,
              strict: false,
            });
          }
        } else {
          matched = !!matchPath(pathname, {
            path: versionPath,
            exact: false,
            strict: false,
          });
        }
      } else if (
        pathnameValue.startsWith(`${versionPathWithoutTrailingSlash}/`) ||
        pathnameValue.startsWith(versionPathWithTrailingSlash)
      ) {
        if (versionPathWithoutTrailingSlash === '/') {
          matched = !!matchPath(pathname, {
            path: versionPath,
            exact: false,
            strict: false,
          });
        } else {
          const prefixLength = versionPathWithoutTrailingSlash.length;
          const boundary = pathnameValue.charAt(prefixLength);
          if (boundary === '/' || boundary === '') {
            if (pathnameSegments.length >= versionSegments.length) {
              matched = !!matchPath(pathname, {
                path: versionPath,
                exact: false,
                strict: false,
              });
            } else {
              matched = !!matchPath(pathname, {
                path: versionPath,
                exact: false,
                strict: false,
              });
            }
          } else {
            matched = !!matchPath(pathname, {
              path: versionPath,
              exact: false,
              strict: false,
            });
          }
        }
      } else {
        matched = !!matchPath(pathname, {
          path: versionPath,
          exact: false,
          strict: false,
        });
      }

      if (matched) {
        return version;
      }
    }

    return undefined;
  } catch (error) {
    if (error instanceof Error) {
      throw unwrapVersionPathError(error);
    }
    throw error;
  }
}

export function getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  const activeVersion = getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find(
    (doc) =>
      !!matchPath(pathname, {
        path: doc.path,
        exact: true,
        strict: false,
      }),
  );

  function getAlternateVersionDocs(
    docId: string,
  ): ActiveDocContext['alternateDocVersions'] {
    const result: ActiveDocContext['alternateDocVersions'] = {};
    data.versions.forEach((version) => {
      version.docs.forEach((doc) => {
        if (doc.id === docId) {
          result[version.name] = doc;
        }
      });
    });
    return result;
  }

  const alternateVersionDocs = activeDoc
    ? getAlternateVersionDocs(activeDoc.id)
    : {};

  return {
    activeVersion,
    activeDoc,
    alternateDocVersions: alternateVersionDocs,
  };
}

export function getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  const latestVersion = getLatestVersion(data);
  const activeDocContext = getActiveDocContext(data, pathname);
  const latestDocSuggestion: GlobalDoc | undefined =
    activeDocContext.alternateDocVersions[latestVersion.name];
  return {latestDocSuggestion, latestVersionSuggestion: latestVersion};
}

